CREATE SCHEMA IF NOT EXISTS kabipay_ops;
CREATE TABLE "kabipay_ops"."billing_cycle" ( "id" uuid NOT NULL PRIMARY KEY, "tenant_id" uuid NOT NULL, "period_start" date NOT NULL, "period_end" date NOT NULL, "frequency" varchar NOT NULL, "status" varchar NOT NULL, "auto_generated_at" timestamp with time zone, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."feature_flag" ( "id" uuid NOT NULL PRIMARY KEY, "tenant_id" uuid NOT NULL, "feature_name" varchar NOT NULL, "is_enabled" bool NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."integration_connector" ( "id" uuid NOT NULL PRIMARY KEY, "name" varchar NOT NULL, "code" varchar NOT NULL, "category" varchar, "auth_type" varchar, "config_schema_json" varchar, "is_active" bool NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."invoice" ( "id" uuid NOT NULL PRIMARY KEY, "tenant_id" uuid NOT NULL, "billing_cycle_id" uuid NOT NULL, "invoice_number" varchar NOT NULL, "subtotal" decimal NOT NULL, "discount_total" decimal NOT NULL, "tax_amount" decimal NOT NULL, "total_amount" decimal NOT NULL, "currency" varchar NOT NULL, "status" varchar NOT NULL, "due_date" date, "sent_at" timestamp with time zone, "paid_at" timestamp with time zone, "is_deleted" bool NOT NULL, "deleted_at" timestamp with time zone, "deleted_by" uuid, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."module" ( "id" uuid NOT NULL PRIMARY KEY, "code" varchar NOT NULL, "name" varchar NOT NULL, "category" varchar, "description" varchar, "is_active" bool NOT NULL, "display_order" integer NOT NULL, "is_core" bool NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."operator_role" ( "id" uuid NOT NULL PRIMARY KEY, "code" varchar NOT NULL, "name" varchar NOT NULL, "description" varchar, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."operator_session" ( "id" uuid NOT NULL PRIMARY KEY, "operator_user_id" uuid NOT NULL, "token_hash" varchar NOT NULL, "ip_address" varchar, "user_agent" varchar, "created_at" timestamp with time zone NOT NULL, "expires_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."operator_user" ( "id" uuid NOT NULL PRIMARY KEY, "email" varchar NOT NULL, "password_hash" varchar NOT NULL, "full_name" varchar NOT NULL, "phone" varchar, "is_active" bool NOT NULL, "last_login_at" timestamp with time zone, "is_deleted" bool NOT NULL, "deleted_at" timestamp with time zone, "deleted_by" uuid, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."operator_user_role" ( "operator_user_id" uuid NOT NULL, "operator_role_id" uuid NOT NULL, "assigned_at" timestamp with time zone NOT NULL, CONSTRAINT "pk-operator_user_role" PRIMARY KEY ("operator_user_id", "operator_role_id") );
CREATE TABLE "kabipay_ops"."payment" ( "id" uuid NOT NULL PRIMARY KEY, "invoice_id" uuid NOT NULL, "amount" decimal NOT NULL, "payment_method" varchar, "status" varchar NOT NULL, "paid_at" timestamp with time zone, "gateway_ref" varchar, "failure_reason" varchar, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."tenant" ( "id" uuid NOT NULL PRIMARY KEY, "name" varchar NOT NULL, "status" varchar NOT NULL, "plan" varchar, "country" varchar, "timezone" varchar, "currency" varchar, "gstin" varchar, "pan" varchar, "registered_address" varchar, "logo_url" varchar, "primary_color" varchar, "subdomain" varchar, "account_manager_id" uuid, "is_deleted" bool NOT NULL, "deleted_at" timestamp with time zone, "deleted_by" uuid, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."tenant_database" ( "id" uuid NOT NULL PRIMARY KEY, "tenant_id" uuid NOT NULL, "db_type" varchar NOT NULL, "db_host" varchar NOT NULL, "db_name" varchar NOT NULL, "schema_name" varchar NOT NULL, "is_active" bool NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );
CREATE TABLE "kabipay_ops"."tenant_subscription" ( "id" uuid NOT NULL PRIMARY KEY, "tenant_id" uuid NOT NULL, "module_id" uuid NOT NULL, "status" varchar NOT NULL, "activated_at" date, "expires_at" date, "contracted_seats" integer NOT NULL, "current_seat_usage" integer NOT NULL, "overage_policy" varchar NOT NULL, "approved_by" uuid, "is_deleted" bool NOT NULL, "deleted_at" timestamp with time zone, "deleted_by" uuid, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL );

CREATE TABLE kabipay_ops.module_dependency(module_id UUID NOT NULL,depends_on_module_id UUID NOT NULL,PRIMARY KEY(module_id,depends_on_module_id));
